#!/usr/bin/env python3
"""Generate the client runtime requirements from pyproject.toml."""

from __future__ import annotations

import argparse
import difflib
import tomllib
from pathlib import Path


ROOT = Path(__file__).resolve().parent.parent
PROJECT = ROOT / "pyproject.toml"
REQUIREMENTS = ROOT / "requirements.txt"


def expected_contents() -> str:
    project = tomllib.loads(PROJECT.read_text(encoding="utf-8"))["project"]
    dependencies = project["dependencies"]
    return (
        "# Generated by scripts/sync-requirements.py from pyproject.toml.\n"
        "# Run from the repository root so patched wheels resolve from dependencies/.\n"
        "--find-links dependencies\n"
        + "\n".join(dependencies)
        + "\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if requirements.txt is stale")
    args = parser.parse_args()
    expected = expected_contents()
    if args.check:
        actual = REQUIREMENTS.read_text(encoding="utf-8") if REQUIREMENTS.exists() else ""
        if actual == expected:
            print("requirements.txt matches pyproject.toml")
            return 0
        diff = difflib.unified_diff(
            actual.splitlines(keepends=True),
            expected.splitlines(keepends=True),
            fromfile="requirements.txt",
            tofile="generated requirements.txt",
        )
        print("".join(diff), end="")
        return 1
    REQUIREMENTS.write_text(expected, encoding="utf-8")
    print("requirements.txt updated from pyproject.toml")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
